// --- Tab bar ---

func overviewTabHref(props InstallOverviewPageProps, tab string) string {
	return utils.NewURL(props.BasePath, "installs", props.Install.ID, "overview").
		Set("tab", overviewTabParam(tab)).
		Build()
}

func overviewTabSwitchAttrs(showID, hideID, href string) templ.Attributes {
	js := "event.preventDefault();" +
		"document.getElementById('" + showID + "').classList.remove('hidden');" +
		"document.getElementById('" + hideID + "').classList.add('hidden');" +
		"this.classList.add('active');" +
		"var sibs=this.parentElement.querySelectorAll('.nav-item');for(var i=0;i<sibs.length;i++){if(sibs[i]!==this)sibs[i].classList.remove('active');};" +
		"history.pushState(null,'','" + href + "');"
	return templ.Attributes{"onclick": js}
}

